import{_ as l,a0 as o,w as p,s as r,I as a,x as e,a1 as t,A as n,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Fedora、CentOS、RHEL 中启用 RPM Fusion 仓库 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora、CentOS、RHEL 中启用 RPM Fusion 仓库 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora、CentOS、RHEL 中启用 RPM Fusion 仓库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora、CentOS、RHEL 中启用 RPM Fusion 仓库 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221002 How to Enable RPM Fusion Repo in Fedora, CentOS, RHEL","title":"如何在 Fedora、CentOS、RHEL 中启用 RPM Fusion 仓库","tag":"202210","desc":""},"relativePath":"202210/20221002 How to Enable RPM Fusion Repo in Fedora, CentOS, RHEL.md","filePath":"[post].md"}'),h={name:"202210/20221002 How to Enable RPM Fusion Repo in Fedora, CentOS, RHEL.md"};function g(u,s,k,c,f,b){const i=o("Link");return p(),r("div",null,[s[17]||(s[17]=a("h1",{id:"如何在-fedora、centos、rhel-中启用-rpm-fusion-仓库",tabindex:"-1"},[e("如何在 Fedora、CentOS、RHEL 中启用 RPM Fusion 仓库 "),a("a",{class:"header-anchor",href:"#如何在-fedora、centos、rhel-中启用-rpm-fusion-仓库","aria-label":"Permalink to “如何在 Fedora、CentOS、RHEL 中启用 RPM Fusion 仓库”"},"​")],-1)),s[18]||(s[18]=a("blockquote",null,[a("p",null,"本指南解释了在 Fedora Linux 发行版中启用第三方软件仓库 RPM Fusion 的步骤。")],-1)),a("p",null,[t(i,{href:"https://rpmfusion.org/"},{default:n(()=>[...s[0]||(s[0]=[e("RPM Fusion",-1)])]),_:1}),s[1]||(s[1]=e(" 软件仓库是一个社区维护的软件仓库，它为 Fedora Linux 提供额外的软件包，这些软件包不是由 Fedora 官方团队分发，例如 DVD 播放、媒体播放、来自 GNOME 和 KDE 的软件等。这是因为许可证、其他法律原因和特定国家/地区的软件规范而导致的。",-1))]),s[19]||(s[19]=d('<p>RPM Fusion 为 Red Hat Enterprise Linux（RHEL）以及 Fedora 提供了 .rpm 包。</p><p>本指南介绍了在 Fedora Linux 中启用 RPM Fusion 仓库所需的步骤。本指南适用于所有 Fedora 发行版本。</p><p>这在所有当前支持的 Fedora 版本（35、36 和 37）中进行了测试。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202210/16/111338jjr0eh5cjgq017n5.jpg" alt=""></p><h3 id="如何在-fedora-linux、rhel、centos-中启用-rpm-fusion-仓库" tabindex="-1">如何在 Fedora Linux、RHEL、CentOS 中启用 RPM Fusion 仓库 <a class="header-anchor" href="#如何在-fedora-linux、rhel、centos-中启用-rpm-fusion-仓库" aria-label="Permalink to “如何在 Fedora Linux、RHEL、CentOS 中启用 RPM Fusion 仓库”">​</a></h3><p>RPM Fusion 有两种版本的仓库：自由和非自由。</p><p>顾名思义，自由版包含软件包的自由版本，非自由版包含封闭源代码的编译软件包和“非商业”开源软件。</p><p>在继续之前，首先检查你是否安装了 RPM fusion。打开终端并运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf repolist | grep rpmfusion</span></span></code></pre></div><p>如果安装了 RPM，你应该会看到如下所示的消息。就不用下面的步骤。如果未安装，你可以继续执行以下步骤。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/07/RPM-Fusion-Already-Installed-.png" alt="RPM Fusion 已安装"></p><p>打开终端并根据你的操作系统版本运行以下命令。请注意，这些命令包含自由和非自由版本。如果你愿意，你可以在运行时省略下面的任何一个。</p><h4 id="fedora" tabindex="-1">Fedora <a class="header-anchor" href="#fedora" aria-label="Permalink to “Fedora”">​</a></h4><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://download1.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://download1.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><h4 id="在-silverblue-上使用-rpm-ostree" tabindex="-1">在 Silverblue 上使用 rpm-ostree <a class="header-anchor" href="#在-silverblue-上使用-rpm-ostree" aria-label="Permalink to “在 Silverblue 上使用 rpm-ostree”">​</a></h4><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rpm-ostree install https://download1.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rpm-ostree install https://download1.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><h4 id="rhel-8" tabindex="-1">RHEL 8 <a class="header-anchor" href="#rhel-8" aria-label="Permalink to “RHEL 8”">​</a></h4><p>先安装 EPEL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm</span></span></code></pre></div><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://download1.rpmfusion.org/free/el/rpmfusion-free-release-8.noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheckhttps://download1.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-8.noarch.rpm</span></span></code></pre></div><p>开发相关软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo subscription-manager repos --enable &quot;codeready-builder-for-rhel-8-$(uname -m)-rpms&quot;</span></span></code></pre></div><h4 id="centos-8" tabindex="-1">CentOS 8 <a class="header-anchor" href="#centos-8" aria-label="Permalink to “CentOS 8”">​</a></h4><p>先安装 EPEL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm</span></span></code></pre></div><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://download1.rpmfusion.org/free/el/rpmfusion-free-release-8.noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheckhttps://download1.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-8.noarch.rpm</span></span></code></pre></div><p>启用 PowerTools：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf config-manager --enable PowerTools</span></span></code></pre></div><h3 id="附加说明" tabindex="-1">附加说明 <a class="header-anchor" href="#附加说明" aria-label="Permalink to “附加说明”">​</a></h3><p>RPM Fusion 还可以帮助用户安装来自 GNOME 软件或 KDE Discover 的软件包。要在 Fedora 中启用它，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate core</span></span></code></pre></div><p>你还可以通过以下命令启用 RPM Fusion 来使用 gstreamer 和其他多媒体播放包来播放媒体文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate multimedia --setop=&quot;install_weak_deps=False&quot; --exclude=PackageKit-gstreamer-plugin</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate sound-and-video</span></span></code></pre></div><p>启用 RPM Fusion 以使用 libdvdcss 播放 DVD。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install rpmfusion-free-release-taintedsudo dnf install libdvdcss</span></span></code></pre></div><p>通过以下命令启用 RPM Fusion 以启用非 FLOSS 硬件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install rpmfusion-nonfree-release-taintedsudo dnf install *-firmware</span></span></code></pre></div><p>运行命令后，如果你使用的是 Fedora 或 CentOS/RHEL，请在重启前运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf check-updatesudo dnf update</span></span></code></pre></div><h3 id="如何使用-dnf-删除仓库" tabindex="-1">如何使用 dnf 删除仓库 <a class="header-anchor" href="#如何使用-dnf-删除仓库" aria-label="Permalink to “如何使用 dnf 删除仓库”">​</a></h3><p>如果要删除仓库，请按照以下步骤操作。</p><p>首先，使用以下命令查看添加到 Fedora 系统的仓库列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf repolist</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/07/dnf-repolist.jpg" alt="dnf 仓库列表"></p><p>如你所见，添加了 rpmfusion 自由和非自由仓库。要通过 dnf 删除它，你需要使用以下命令准确知道仓库文件名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rpm -qa &#39;rpmfusion*&#39;</span></span></code></pre></div><p>这将列出仓库的确切名称。在示例中，它们是 “rpmfusion-free-release”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/07/remove-rpmfusion-from-fedora.jpg" alt="从 Fedora 中移除 rpmfusion"></p><p>现在你可以简单地运行以下命令来删除它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf remove rpmfusion-free-release</span></span></code></pre></div><p>你可以重复上面的例子从 Fedora 中删除 rpmfusion，也可以使用它从系统中删除任何其他仓库。</p><hr>',65)),a("p",null,[s[3]||(s[3]=e("via: ",-1)),t(i,{href:"https://www.debugpoint.com/enable-rpm-fusion-fedora-rhel-centos/"},{default:n(()=>[...s[2]||(s[2]=[e("https://www.debugpoint.com/enable-rpm-fusion-fedora-rhel-centos/",-1)])]),_:1})]),a("p",null,[s[8]||(s[8]=e("作者：",-1)),t(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...s[4]||(s[4]=[e("Arindam",-1)])]),_:1}),s[9]||(s[9]=e(" 选题：",-1)),t(i,{href:"https://github.com/lkxed"},{default:n(()=>[...s[5]||(s[5]=[e("lkxed",-1)])]),_:1}),s[10]||(s[10]=e(" 译者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[6]||(s[6]=[e("geekpi",-1)])]),_:1}),s[11]||(s[11]=e(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[13]||(s[13]=[e("Linux中国",-1)])]),_:1}),s[16]||(s[16]=e(" 荣誉推出",-1))])])}const v=l(h,[["render",g]]);export{y as __pageData,v as default};
